// iconButton uses MyGo's standard Button and Icon, including focus and tooltips.
func iconButton(c *ui.Context, name, label string) ui.Element {
	t := c.Theme()
	c.Key(label)
	b := ui.Button(c, "").Label(label).Tooltip(label).Size(t.Space(7), t.Space(7)).Padding(0).Radius(t.Radius).Border(0, ui.Transparent).Background(ui.Transparent).Children(func() { ui.Icon(c, icons[name]).Size(t.Rem(1.3), t.Rem(1.3)) })
	if b.Hovered() {
		b.Background(t.SurfaceHover)
	}
	return b
}

func iconTextButton(c *ui.Context, iconName, text, label string, primary bool) ui.Element {
	if label == "" {
		label = text
	}
	t := c.Theme()
	c.Key(label)
	b := ui.Button(c, "")
	if primary {
		b = ui.PrimaryButton(c, "")
	}
	return b.Label(label).Children(func() {
		ui.Icon(c, icons[iconName]).Size(t.Rem(1.1), t.Rem(1.1))
		ui.Text(c, text).SingleLine()
	})
}
